def main():
    for cid, d in CORPUS.items():
        p = BASE / "corpus" / "skills" / cid / "SKILL.md"
        p.parent.mkdir(parents=True, exist_ok=True)
        txt = ("---\nname: " + cid + "\ndescription: " + d["description"]
               + "\n---\n\n" + d["body"] + "\n")
        p.write_text(txt, encoding="utf-8")
    print("regenerated", len(CORPUS), "skills")

if __name__ == "__main__":
    main()
